// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address caller) public {
        vm.assume(caller != address(0));
        // First transfer ownership to the caller (so they become pending owner)
        address currentOwner = c.owner();
        vm.prank(currentOwner);
        c.transferOwnership(caller);
        // Now caller accepts ownership
        vm.prank(caller);
        c.acceptOwnership();
        // The owner should be the caller
        assertTrue(c.owner() == caller);
    }
}

